lemma L_nths: "S \<subseteq> {..<length init}
  \<Longrightarrow> map_pmf (\<lambda>l. nths l S) (Prob_Theory.bv (length init))
      = (Prob_Theory.bv (length (nths init S)))"

trg:
using assms(2) proof (prove)
using this:
c \<le> c'

goal (1 subgoal):
 1. compet A c' S0
using assms(1) by (auto simp: compet_def)
end

