proof (induct rule: boundOutputInduct)
  case (Match P a x P' b C)
  from `P \<longmapsto>a<\<nu>x> \<prec> P'` `x \<sharp> P` show ?case by(rule cMatch)
next
  case (Mismatch P a x P' b c C)
  from `P \<longmapsto>a<\<nu>x> \<prec> P'` `x \<sharp> P` show ?case by(rule cMismatch)
next
  case (Open P a x P' C)
  from `P \<longmapsto>(OutputR a x) \<prec> P'` `a \<noteq> x` show ?case by(rule cOpen)
next
  case (Sum1 P Q a x P' C)
  from `P \<longmapsto>a<\<nu>x> \<prec> P'` `x \<sharp> P` show ?case by(rule cSum1)
next
  case (Sum2 P Q a x Q' C)
  from `Q \<longmapsto>a<\<nu>x> \<prec> Q'` `x \<sharp> Q` show ?case by(rule cSum2)
next
  case (Par1B P P' Q a x C)
  from `P \<longmapsto>a<\<nu>x> \<prec> P'` `x \<sharp> Q` show ?case by(rule cPar1B)
next
  case (Par2B P Q Q' a x C)
  from `Q \<longmapsto>a<\<nu>x> \<prec> Q'` `x \<sharp> P` show ?case by(rule cPar2B)
next
  case (ResB P P' a x y C)
  from `P \<longmapsto>a<\<nu>x> \<prec> P'` `y \<noteq> a` `y \<noteq> x` `y \<sharp> C` show ?case by(rule cResB)
next
  case (Bang P a x P' C)
  from `P \<parallel> !P \<longmapsto>a<\<nu>x> \<prec> P'` `x \<sharp> P` show ?case by(rule cBang)
qed

